import {hasFieldOrderDraft,hasInvoiceHold,exceptionWorkspace,installExceptionWorkspaces,reviewMeterRead} from './exceptions.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icons={cog:'m10 2-.7 2.8-2.1 1.2-2.8-.8-2 3.5 2.1 2v2.6l-2.1 2 2 3.5 2.8-.8 2.1 1.2.7 2.8h4l.7-2.8 2.1-1.2 2.8.8 2-3.5-2.1-2v-2.6l2.1-2-2-3.5-2.8.8L14.7 4.8 14 2ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',town:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8',play:'m9 5 11 7-11 7Z',billing:'M6 3h12v18l-3-2-3 2-3-2-3 2ZM9 7h6M9 11h6M9 15h3',chart:'M4 3v17h17M8 16v-5M13 16V7M18 16V4',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',layers:'m3 7 9-5 9 5-9 5ZM3 12l9 5 9-5M3 17l9 5 9-5',check:'m5 12 4 4L19 6',lock:'M7 10V7a5 5 0 0110 0v3M5 10h14v11H5ZM12 14v3',clock:'M12 8v5l3 2M22 12a10 10 0 11-20 0 10 10 0 0120 0',search:'M21 21l-6-6M17 10a7 7 0 11-14 0 7 7 0 0114 0',arrow:'M5 12h14M14 7l5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',bolt:'m14 2-9 12h7l-2 8 9-12h-7Z',activity:'M2 12h5l3-8 4 16 3-8h5',users:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2M13 6a4 4 0 11-8 0 4 4 0 018 0M17 3a4 4 0 010 8M22 21v-2a4 4 0 00-3-3.87',mail:'M3 5h18v14H3Zm0 0 9 7 9-7',file:'M14 2H5v20h14V7ZM14 2v6h5M8 12h8M8 16h8',flask:'M9 3h6M10 3v6L4 19a2 2 0 002 2h12a2 2 0 002-2L14 9V3M7 15h10',external:'M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7',coin:'M12 6v12M16 8h-6a3 3 0 000 6h4a3 3 0 000-6M22 12a10 10 0 11-20 0 10 10 0 0120 0'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const concepts={guided:{label:'Guided run',note:'One clear sequence. Configure the town, preview a run, work the billing queue, then review the outcome.',best:'The clearest everyday workflow. Recommended starting point.'},control:{label:'Mission control',note:'One operating dashboard. Queues, costs, run status and the billing back office stay one click away.',best:'Best for daily operations and monitoring many exceptions.'},experiment:{label:'Experiment studio',note:'One controlled comparison. Hold the town constant and see the effect of changing process assumptions.',best:'Best for testing automation, staffing and the business case.'},spatial:{label:'Town workspace',note:'One persistent town. Configuration, cases and billing open alongside the existing 3D view.',best:'Best for live demos and tracing an exception back to a property.'}};
const stages=[['config','Configure','settings'],['simulation','Simulate','play'],['billing','VEE & billing','billing'],['results','Results','chart']];
const state={concept:'guided',page:'config',configTab:'process',config:{seed:'WHITBY-042',homes:480,ami:60,coverage:35,queue:2,carry:1.25,scenario:'Normal day'},revision:1,savedRevision:1,run:42,asOf:'2026-10-01',hour:8,playing:false,queue:'All cases',search:'',sapTab:'orders',sapTransaction:'exceptions',sapRecord:'',lastSapRoute:'#experiment/sap/exceptions',sapParent:'billing',billingIndex:null,readIndex:null,readOrigin:null,queryKind:'',queryValue:'',queryError:'',selected:0,resolved:new Set(),dirty:false};
const cases=[{id:'C-0421',type:'Consecutive estimates',address:'42 Cedar Lane',account:'2100000101',utility:'Gas',queue:'Missing reads',impact:418,age:8,confidence:42,next:'Review read history',priority:'High',code:'SIM-P01'}, {id:'C-0318',type:'High usage',address:'18 Maple Crescent',account:'2100000318',utility:'Water',queue:'VEE review',impact:362,age:5,confidence:58,next:'Check consumption',priority:'High',code:'SIM-T01'}, {id:'C-0276',type:'Register regression',address:'76 Brock Street',account:'2100000276',utility:'Electric',queue:'Escalations',impact:287,age:4,confidence:21,next:'Supervisor review',priority:'High',code:'SIM-C01'}, {id:'C-0189',type:'No access',address:'89 Garden Street',account:'2100000189',utility:'Water',queue:'Field orders',impact:146,age:3,confidence:null,next:'Review field order',priority:'Medium',code:'—'}, {id:'C-0116',type:'Comm fail',address:'16 Ash Court',account:'2100000116',utility:'Gas',queue:'Missing reads',impact:24,age:2,confidence:null,next:'Review estimate',priority:'Low',code:'—'}];
const route=(p,c=state.concept)=>{if(c==='experiment'){if(p==='billing')p='sap/exceptions';else if(p==='vee'||p==='exceptions'||p.startsWith('exceptions/'))p='sap/'+p;}return `#${c}/${p}`;};
const btn=(label,action,primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,p,primary=false)=>`<a class="btn ${primary?'primary':''}" href="${route(p)}">${label}</a>`;
const money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);
const sapTransactions=[
 ['Worklists','exceptions','Clarification Case List'],
 ['Worklists','vee','Resolve Implausible Meter Readings'],
 ['Display','billing-query','Display Billing'],
 ['Display','read-query','Display Meter Reading Results']
];
const billingScreens=['orders','periods','documents','document','invoice','contract','installation'];
const readingScreens=['reads','device','rates'];
const sapScreenNames={'field-order':'Create Field Service Order',orders:'Billing Details',periods:'Billing Periods',documents:'Billing Documents',document:'Display Billing Document',invoice:'Display Print Document',contract:'Display Contract',installation:'Display Installation',reads:'Meter Reading Results',device:'Display Device and Register',rates:'Display Rate Data'};
const installationId=index=>'710000'+cases[index].id.slice(2);
const meterReadId=index=>'MR-2026-'+cases[index].id.slice(2);
function sapTransactionHeader(transaction,record='',titleOverride=''){
 const groups=[...new Set(sapTransactions.map(t=>t[0]))],isList=['exceptions','vee'].includes(transaction)&&!record,currentTitle=titleOverride||(record?'Clarification Case Detail':sapScreenNames[transaction]);
 return `<header class="sap-transaction-header ${record?'sap-transaction-classic':''}"><span class="sap-emblem">SAP</span><select id="sap-transaction" aria-label="SAP transaction">${currentTitle?`<option value="current-screen" selected disabled>${currentTitle}</option>`:''}${groups.map(group=>`<optgroup label="${group}">${sapTransactions.filter(t=>t[0]===group).map(([,id,label])=>`<option value="${id}" ${!currentTitle&&id===transaction?'selected':''}>${label}</option>`).join('')}</optgroup>`).join('')}</select><span class="spacer"></span>${isList?`<button data-x-act="focus-search" aria-label="Search records" title="Search records">${icon('search')}</button>`:''}<small>100</small></header>`;
}
function goSapScreen(screen){const target=route('sap/'+screen,'experiment');if(location.hash===target)render();else location.hash=target;}
function openSapTransaction(transaction){
 if(transaction==='current-screen')return;
 if(billingScreens.includes(transaction))transaction='billing-query';
 if(readingScreens.includes(transaction))transaction='read-query';
 if(!sapTransactions.some(t=>t[1]===transaction))return;
 if(state.page==='sap'&&['exceptions','vee'].includes(state.sapTransaction))state.worklistReturn=state.lastSapRoute;
 if(transaction.endsWith('-query')){state.billingIndex=null;state.readIndex=null;state.readOrigin=null;state.queryKind=transaction;state.queryValue='';state.queryError='';}
 goSapScreen(transaction);
}
function openSapRelated(transaction){
 const inRecord=state.page==='sap'&&Object.hasOwn(sapScreenNames,state.sapTransaction),billingReady=state.billingIndex===state.selected,readingReady=state.readIndex===state.selected;
 if(!inRecord){openSapTransaction(transaction);return;}
 if(billingScreens.includes(transaction)){
  if(!billingReady){openSapTransaction('billing-query');return;}
 }else if(readingScreens.includes(transaction)){
  if(!readingReady&&!billingReady){openSapTransaction('read-query');return;}
  if(!cases[state.selected].readDetails&&transaction==='reads'){toast('No meter-reading result is available for this sample installation.');return;}
  if(!readingReady){state.readIndex=state.selected;state.readOrigin=state.lastSapRoute;}
 }else return;
 goSapScreen(transaction);
}
function canReviewMeterRead(index){return state.page==='sap'&&state.sapTransaction==='reads'&&state.readIndex===index;}
function queryScreen(kind){
 const billing=kind==='billing-query',label=billing?'Installation':'Meter reading document';
 return `<section class="sap-app sap-query-app">${sapTransactionHeader(kind)}<form id="sap-query-form" data-query-kind="${kind}"><div class="sap-toolbar"><button type="submit">${icon('check')} Execute</button><button type="button" data-action="query-clear">Clear</button></div><div class="sap-query-body"><section class="gui-group"><h3>Selection</h3><div class="gui-group-body"><div class="sap-query-field"><label for="sap-query-id">${label}</label><input id="sap-query-id" name="identifier" value="${esc(state.queryValue)}" required autocomplete="off" spellcheck="false" maxlength="40" aria-describedby="sap-query-error"><button type="button" data-action="query-help" aria-label="Find ${label.toLowerCase()}" title="Possible entries (F4)">▣</button></div><p id="sap-query-error" role="alert">${esc(state.queryError)}</p></div></section></div></form><div class="sap-status"><span class="sap-square green"></span> Enter ${billing?'an installation':'a meter-reading document'} and choose Execute.<span class="spacer"></span>Sample data</div></section>`;
}
function submitSapQuery(kind,raw){
 if(!['billing-query','read-query'].includes(kind))return false;
 const value=String(raw||'').trim().toUpperCase(),billing=kind==='billing-query';state.queryKind=kind;state.queryValue=value;
 const index=cases.findIndex((c,i)=>billing?installationId(i)===value:!!c.readDetails&&meterReadId(i)===value);
 if(index<0){state.queryError=value?`No ${billing?'installation':'meter-reading document'} found for ${value}.`:`Enter ${billing?'an installation':'a meter-reading document'}.`;render();return false;}
 state.queryError='';state.selected=index;state.billingIndex=billing?index:null;state.readIndex=billing?null:index;state.readOrigin=billing?null:route('sap/read-query','experiment');goSapScreen(billing?'orders':'reads');return true;
}
function queryHelp(){
 const billing=state.sapTransaction==='billing-query',label=billing?'Installation':'Meter reading document';
 openDialog('Possible Entries · '+label,`<div class="sap-query-help"><table><thead><tr><th>${label}</th><th>Contract account</th><th>Premise</th></tr></thead><tbody>${cases.map((c,i)=>({c,i})).filter(({c})=>billing||c.readDetails).map(({c,i})=>`<tr><td><button class="sap-link" data-query-pick="${billing?installationId(i):meterReadId(i)}">${billing?installationId(i):meterReadId(i)}</button></td><td>${c.account}</td><td>${esc(c.address)}</td></tr>`).join('')}</tbody></table></div>`);
}
function sapRecordToolbar(tab){
 const billingReady=state.billingIndex===state.selected,back=tab==='reads'&&state.readOrigin?`<button data-action="read-back">‹ Back</button>`:billingReady?`<button data-sap="orders">‹ Billing details</button>`:'';
 return `<div class="sap-toolbar">${back}<button data-action="query-new" data-query-kind="${billingReady?'billing-query':'read-query'}">New selection</button>${billingReady?`<button data-sap="installation">${icon('town')} Installation</button><button data-sap="contract">${icon('file')} Contract</button>`:''}${billingReady&&cases[state.selected].readDetails?`<button data-sap="reads">${icon('grid')} MR results</button>`:''}${tab==='reads'?`<button data-action="sap-release" ${state.resolved.has(cases[state.selected].id)?'disabled':''}>Review / release</button>`:''}<span class="sap-toolbar-rule"></span><button data-action="sap-worklist">Back to case / list</button></div>`;
}
function sapRecordTabs(tab){const tabs=state.billingIndex===state.selected?[['orders','Bil. Order'],['periods','Bil.Time'],['documents','Documents']]:[['reads','MR result'],['device','Register'],['rates','Rate data']];return `<nav class="sap-tabs" aria-label="Record sections">${tabs.map(([id,label])=>`<button data-sap="${id}" class="${id===tab?'active':''}">${icon('grid')}${label}</button>`).join('')}</nav>`;}
function sapWorkspace(){if(['exceptions','vee','field-order'].includes(state.sapTransaction))return exceptionWorkspace(state.sapTransaction,state.sapRecord);if(state.sapTransaction.endsWith('-query'))return queryScreen(state.sapTransaction);return sapPage(true);}
function field(name,label,type='number',hint=''){const v=state.config[name];return `<div class="field"><label for="${name}">${label}</label><input id="${name}" data-config="${name}" type="${type}" value="${esc(v)}" ${name==='homes'?'min="20" max="10000"':name==='queue'?'min="1" max="20"':name==='carry'?'min="0" max="20" step="0.25"':''}><div class="hint">${hint}</div></div>`;}
function slider(name,label,min,max,suffix,hint=''){return `<div class="field"><div class="field-top"><label for="${name}">${label}</label><span class="value" data-value="${name}">${state.config[name]}${suffix}</span></div><input id="${name}" data-config="${name}" type="range" min="${min}" max="${max}" value="${state.config[name]}" data-suffix="${suffix}"><div class="hint">${hint}</div></div>`;}
function brand(title='Utility Sim'){return `<div class="brand"><span class="logo">u</span><span>${title}</span></div>`;}
function contextTop(){return `<header class="top">${brand()}<span class="separator"></span><span class="run-id"><b>Whitby / October cycle</b> &nbsp; · &nbsp; Run ${state.run.toString().padStart(3,'0')}</span><span class="spacer"></span><span class="pill neutral">Sample run</span><span class="avatar">GE</span></header>`;}
function stepper(){let index=stages.findIndex(s=>s[0]===state.page);if(state.page==='sap')index=2;return `<nav class="steps" aria-label="Simulation workflow">${stages.map(([p,l],i)=>`<a href="${route(p)}" class="step ${i===index?'active':i<index?'complete':''}" ${i===index?'aria-current="step"':''}><span class="num">${i<index?'✓':i+1}</span><span><b>${l}</b><small>${['Town & run settings','Clock & events','Exceptions & back office','Performance & cost'][i]}</small></span></a>`).join('')}</nav>`;}
function heading(title,subtitle,action='',kicker='WHITBY / OCTOBER 2026'){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function map(height='map-large'){return `<div class="map-card ${height}"><div class="map-slot"></div><div class="map-title"><b>Whitby · Existing town renderer</b><small>480 homes · 3 utility networks</small></div><div class="map-tools"><button data-action="layer" data-layer="electric" class="on" title="Electric network">ϟ</button><button data-action="layer" data-layer="water" title="Water network">W</button><button data-action="layer" data-layer="gas" title="Gas network">G</button><button data-action="fit" title="Fit town">${icon('town')}</button></div><div class="map-caption">Drag to pan · Right-drag to orbit · Scroll to zoom · © OpenStreetMap contributors</div></div>`;}
function summary(){return `<aside class="card summary-card"><div class="label">Your run, in one place</div><div class="summary-title">Whitby / October cycle</div><p class="small">The same town and run follow you through every page.</p><div class="section-rule"></div><div class="details-list"><span>Town seed</span><strong>${esc(state.config.seed)}</strong><span>Residential homes</span><strong>${state.config.homes.toLocaleString()}</strong><span>Run</span><strong>SIM-${state.run.toString().padStart(3,'0')}</strong><span>View date</span><strong>01 Oct 2026</strong><span>Configuration</span><strong>Revision ${state.revision}</strong></div><div class="section-rule"></div><div class="row">${icon('layers')}<h3>Connected to this run</h3></div><div class="event-list" style="margin-top:20px">${[['Town snapshot','Geography, customers & devices'],['VEE and worklists','Reads, cases & analyst actions'],['Billing back office','Installation, contract & documents'],['Run results','Release time, processing & carry cost']].map(([a,b])=>`<div class="event"><span class="event-icon">${icon('check')}</span><div>${a}<p>${b}</p></div></div>`).join('')}</div></aside>`;}
function configForm(){let tab=state.configTab;return `<div class="config-tabs" role="tablist" aria-label="Configuration groups">${[['town','Town & meters'],['process','Process & costs'],['scenario','Scenario']].map(([v,l])=>`<button role="tab" aria-selected="${v===tab}" class="${v===tab?'active':''}" data-tab="${v}">${l}</button>`).join('')}</div>${tab==='town'?`<div class="card"><div class="card-header"><div><h2>Town & metering</h2><p class="small">Start with the existing Whitby preset.</p></div><span class="pill">Town settings</span></div><div class="form-grid">${field('seed','Repeatable seed','text','Same seed and settings reproduce the same town.')}${field('homes','Residential homes','number','20–10,000 homes supported by the engine.')}${slider('ami','AMI route share',0,100,'%','Remaining routes use AMR or manual reading.')}<div class="field"><label>Utilities</label><div class="row wrap"><span class="pill">Electricity</span><span class="pill">Gas</span><span class="pill">Water</span></div><div class="hint">Inherited from the selected town.</div></div></div><div class="impact-note"><b>Changing the town creates a new snapshot.</b> Customers, devices and meter routes are regenerated. This concept preview retains the existing 480-home 3D fixture.</div></div>`:tab==='scenario'?`<div class="card"><div class="card-header"><div><h2>Choose what happens</h2><p class="small">Pair the town with a repeatable scenario.</p></div><span class="pill">Run settings</span></div><div class="form-grid"><div class="field"><label for="scenario">Scenario</label><select id="scenario" data-config="scenario">${['Normal day','Solar export at noon','Water service leak','Substation outage'].map(v=>`<option ${state.config.scenario===v?'selected':''}>${v}</option>`).join('')}</select><div class="hint">Presets from the existing town viewer.</div></div><div class="field"><label for="view-date">View date</label><input type="date" id="view-date" value="2026-10-01" readonly><div class="hint">Fixed date for this design sample.</div></div></div><div class="section-rule"></div><h3>Follow the effect downstream</h3><div class="event-list" style="margin-top:22px"><div class="event"><span class="event-icon">${icon('bolt')}</span><div>Physical event<p>Consumption, service availability or telemetry changes.</p></div></div><div class="event"><span class="event-icon">${icon('billing')}</span><div>Read and process effect<p>VEE decision, queue assignment and release to billing.</p></div></div><div class="event"><span class="event-icon">${icon('chart')}</span><div>Measured outcome<p>Time to release, human touches and processing cost.</p></div></div></div></div>`:`<div class="card"><div class="card-header"><div><h2>How work gets done</h2><p class="small">Control automation and the human queue.</p></div><span class="pill">Run settings</span></div>${slider('coverage','RPA coverage',0,100,'%','Share of exception types covered by an auto-resolution rule.')}<div class="section-rule"></div><div class="form-grid">${field('queue','Analyst queue wait · days','number','Business days before an analyst picks up a case.')}${field('carry','Carrying cost · CAD / account / day','number','Cost accumulated while a bill is held.')}</div><div class="impact-note"><b>What this changes:</b> analyst workload, days to release and the cost of held bills. The town and customer identities stay the same.</div></div><div class="card"><div class="card-header" style="margin-bottom:18px"><h2>Activity costs</h2><span class="small">From the engine catalogue · CAD</span></div><div class="details-list"><span>Analyst review</span><strong>$22.00</strong><span>Auto-resolution</span><strong>$2.00</strong><span>Truck roll</span><strong>$85.00</strong><span>Supervisor review</span><strong>$35.00</strong></div></div>`}`;}
function configPage(){return `${heading('Set up your next run','A single configuration connects the town to the process and its results.',`<span class="pill ${state.dirty?'warn':'good'}" id="config-status">${state.dirty?'Draft changes':'Ready to preview'}</span>`)}<div class="grid2"><div>${configForm()}<div class="footer-action"><span id="draft-note">${state.dirty?'Changes apply to the next preview.':'Current settings are ready.'}</span>${btn('Save settings & open simulation','save',true)}</div></div>${summary()}</div>`;}
function stats(values){return `<div class="stats">${values.map(([label,value,note,i])=>`<div class="stat">${icon(i||'chart')}<div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
function flow(){return `<div class="meter-flow">${[['simulation','Reads collected','1,440','This cycle'],['billing','VEE accepted','1,392','96.7% of reads'],['billing','Open cases',String(48-state.resolved.size),'4 work queues'],['sap','Released to billing',String(1392+state.resolved.size),'SAP-style back office']].map(([p,l,n,s],i)=>`<a href="${route(p)}" class="flow-cell ${state.page===p?'active':''}"><span>${String(i+1).padStart(2,'0')} · ${l}</span><b>${n}</b><span class="small">${s}</span></a>`).join('')}</div>`;}
function events(){return `<div class="event-list">${[['mail','Read collection complete','1,440 sample reads available','01:00'],['check','VEE evaluation complete','1,392 accepted · 48 exceptions','01:04'],['users','Cases assigned to queues','VEE, missing reads, supervisor, field','01:05'],['billing','Billing handoff ready','Carry account context into the back office','01:06']].map(([i,t,n,time])=>`<div class="event"><span class="event-icon">${icon(i)}</span><div>${t}<p>${n}</p></div><time>${time}</time></div>`).join('')}</div>`;}
function simulationPage(){return `${heading('A town. A clock. One connected run.','Preview the same town, then follow its meter reads into the work queue.',link('Open VEE & billing','billing',true))}${flow()}<div class="grid2"><div>${map()}<div class="timeline-controls">${btn(icon('play'),'play')}<div><strong id="clock-value">${String(state.hour).padStart(2,'0')}:00</strong><div class="clock-small">DEMO LIGHTING</div></div><input aria-label="Preview hour" id="clock-slider" type="range" min="0" max="23" value="${state.hour}"><span class="small">01 Oct 2026</span></div></div><div class="card"><div class="card-header"><div><div class="label">Sample event sequence</div><h2 style="margin-top:8px">Read to release</h2></div><span class="pill good">Complete</span></div>${events()}<div class="section-rule"></div><p class="small">The existing town renders here. Event counts and billing outcomes are illustrative design data.</p><div style="margin-top:20px">${link('Inspect a billing case','billing')}</div></div></div>`;}
function queueTable(limit=5){let rows=cases.filter(c=>(state.queue==='All cases'||c.queue===state.queue)&&`${c.id} ${c.type} ${c.address} ${c.account}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="table-wrap"><table><thead><tr><th>Priority</th><th>Exception / premise</th><th>Utility</th><th>Age</th><th>Bill impact</th><th>Next action</th><th></th></tr></thead><tbody>${rows.slice(0,limit).map(c=>`<tr class="case-row" data-case="${cases.indexOf(c)}" tabindex="0" aria-label="Open ${esc(c.type)} at ${esc(c.address)}"><td><span class="priority ${c.priority==='Low'?'low':''}">${c.priority}</span></td><td><strong>${c.type}</strong><small>${c.address} · ${c.id}</small></td><td>${c.utility}</td><td>${c.age} days</td><td><strong>${money(c.impact)}</strong></td><td>${state.resolved.has(c.id)?'<span class="pill good">Released · preview</span>':c.next}</td><td>${icon('external')}</td></tr>`).join('')||'<tr><td colspan="7">No sample cases match this filter.</td></tr>'}</tbody></table></div><div class="table-foot">${rows.length} illustrative cases shown · Select a case to inspect VEE, read history and billing context.</div>`;}
function billingPage(){return `${heading('From exception to released read','Keep the case, customer and billing context together.',link('Open SAP-style back office','sap',true))}${flow()}<div class="card"><div class="card-header"><div><h2>Work the next best action</h2><p class="small">VEE review · Missing reads · Escalations · Field orders</p></div><div class="inline-search">${icon('search')}<input class="filter-input" id="case-search" type="search" placeholder="Find case, account or address" value="${esc(state.search)}" aria-label="Search sample cases"></div></div><div class="queue-tabs">${['All cases','VEE review','Missing reads','Escalations','Field orders'].map(q=>`<button class="queue-tab ${state.queue===q?'active':''}" data-queue="${q}">${q}</button>`).join('')}</div><div id="case-table">${queueTable()}</div></div><div class="footer-action"><span>Release is a process outcome. Billing documents and invoices are inspected in the back office.</span>${link('Review run results','results')}</div>`;}
function chart(){return `<svg class="chart" viewBox="0 0 650 180" preserveAspectRatio="none" role="img" aria-label="Illustrative backlog, baseline versus automation, over four weeks"><path class="chart-grid" d="M0 25H650M0 75H650M0 125H650M0 175H650"/><path class="chart-area" d="M0 67 58 45 116 74 174 85 232 70 290 100 348 113 406 111 464 140 522 141 580 151 650 155V175H0Z"/><path class="chart-secondary" d="M0 67 58 45 116 52 174 37 232 57 290 44 348 66 406 58 464 78 522 71 580 79 650 86"/><path class="chart-line" d="M0 67 58 45 116 74 174 85 232 70 290 100 348 113 406 111 464 140 522 141 580 151 650 155"/></svg><div class="chart-labels"><span>Week 1</span><span>Week 2</span><span>Week 3</span><span>Week 4</span></div>`;}
function costs(){return `<div class="bar-row"><span>Labour</span><div class="bar-track"><i style="width:75%"></i></div><strong>$3,120</strong></div><div class="bar-row"><span>Read collection</span><div class="bar-track"><i style="width:23%;opacity:.7"></i></div><strong>$960</strong></div><div class="bar-row"><span>System & CX</span><div class="bar-track"><i style="width:8%;opacity:.45"></i></div><strong>$360</strong></div><div class="section-rule"></div><div class="row between" style="font-size:14px"><span>Processing total</span><strong>$4,440</strong></div><div class="row between" style="font-size:14px;margin-top:14px"><span class="muted">Carrying cost · separate</span><strong>$825</strong></div>`;}
function resultsPage(){return `${heading('What changed in this run?','Time, work and cost tied back to the exact configuration.',btn(`${icon('download')} Export sample summary`,'export'))}<div class="result-banner"><div><strong>Fewer human touches. Faster release.</strong><p>Illustrative outcome for an automation scenario compared with the same sample population.</p></div><span class="pill">Run SIM-${state.run.toString().padStart(3,'0')}</span></div>${stats([['Average days to release','1.8','Baseline 4.2 days · all cases','clock'],['Human reviews','84','Baseline 240 · this sample','users'],['Processing cost','$4,440','Baseline $8,880 · CAD','coin'],['VEE precision / recall','96% / 93%','Against synthetic truth','check']])}<div class="grid2"><div class="card"><div class="card-header"><h2>Open exception backlog</h2><div class="legend"><span><i class="grey"></i>Baseline</span><span><i></i>Automation</span></div></div>${chart()}<div class="impact-note">Click through to an underlying case or reopen the settings behind the run. <b>Every outcome stays traceable.</b></div></div><div class="card"><div class="card-header"><h2>Cost of processing</h2><span class="small">CAD</span></div>${costs()}</div></div><div class="footer-action"><span>Illustrative values · Not engine-generated results · Last configuration revision ${state.savedRevision}</span><div class="row">${link('Inspect worklists','billing')}${link('Adjust configuration','config',true)}</div></div>`;}
function controlOverview(){return `${heading('October cycle overview','The whole meter-to-cash run, without losing your place.',link('Run settings','config'))}${stats([['Reads evaluated','1,440','Current sample cycle','activity'],['Released to billing',String(1392+state.resolved.size),'96.7% first-pass acceptance','billing'],['Cases awaiting action',String(48-state.resolved.size),'5 shown below · 4 queues','users'],['Processing + carrying','$5,265','$4,440 processing · $825 carry','coin']])}${flow()}<div class="ops-grid"><div class="card"><div class="card-header"><div><h2>Exceptions needing attention</h2><p class="small">Prioritised by bill impact and age</p></div>${link('All worklists','billing')}</div>${queueTable(4)}</div><div class="card"><div class="card-header"><h2>Run health</h2><span class="pill good">Sample complete</span></div><div class="mini-score"><span>VEE review</span><b>18</b></div><div class="mini-score"><span>Missing reads</span><b>21</b></div><div class="mini-score"><span>Escalations</span><b>4</b></div><div class="mini-score"><span>Field orders</span><b>5</b></div><div class="section-rule"></div><p class="small">From a case, open its installation in the SAP-style back office.</p><div style="margin-top:15px">${link('Billing back office','sap',true)}</div></div></div>`;}
function guided(){return `<div class="shell guided">${contextTop()}${stepper()}<main class="page">${content()}</main></div>`;}
function control(){return `<div class="shell control"><aside class="side">${brand()}<div class="label">Workspace</div>${[['overview','Overview','grid'],...stages,['sap','Billing back office','file']].map(([p,l,i])=>`<a class="nav-link ${state.page===p?'active':''}" href="${route(p)}">${icon(i)}<span>${l}</span></a>`).join('')}<div class="side-bottom"><div class="label" style="padding:0">Selected town</div>Whitby · WHITBY-042<br>480 homes<br><br>Illustrative design preview</div></aside><div><header class="top"><span class="small">${state.page==='overview'?'Workspace overview':stages.find(s=>s[0]===state.page)?.[1]||'Billing back office'}</span><span class="spacer"></span><span class="run-id">Whitby &nbsp; / &nbsp; <b>SIM-${state.run.toString().padStart(3,'0')}</b></span><span class="pill">01 Oct 2026</span><span class="avatar">GE</span></header><main class="page">${state.page==='overview'?controlOverview():content()}</main></div></div>`;}
function experimentSetup(){return `${heading('What if more exceptions resolved themselves?','Keep the town fixed. Change the process. Compare the outcome.',btn('Preview comparison','compare',true),'EXPERIMENT 007 / AUTOMATION COVERAGE')}<div class="studio-ribbon">${icon('lock')}<span>Same town <b>Whitby · 480 homes</b></span><span>Same seed <b>WHITBY-042</b></span><span>Same period <b>October 2026</b></span><span>Same read population <b>1,440</b></span></div><div class="compare-grid"><div class="compare-card context-card"><div><div class="compare-id">01 / Shared context</div><h2>One town.<br>Two approaches.</h2><p class="small">Isolate the process change.</p></div><div class="section-rule"></div><div class="details-list"><span>Scenario</span><strong>Normal day</strong><span>Utilities</span><strong>Electric / gas / water</strong><span>Carry rate</span><strong>$1.25 / day</strong></div><div class="locked">${icon('lock')} Geography & customers fixed</div></div><div class="compare-card"><div class="compare-id">A / Baseline</div><h2>Current process</h2><p class="small">The reference to compare against.</p><div class="section-rule"></div><div class="details-list"><span>RPA coverage</span><strong>35%</strong><span>Analyst queue</span><strong>2 days</strong><span>Review cost</span><strong>$22 / review</strong><span>Truck roll</span><strong>$85 / visit</strong></div><div class="locked" style="margin-top:65px">${icon('lock')} Baseline held constant</div></div><div class="compare-card variant"><div class="compare-id">B / Treatment</div><h2>More automation</h2><p class="small">Change one assumption at a time.</p>${slider('coverage','RPA coverage',0,100,'%','Draft setting for a future engine run.')}${field('queue','Analyst queue · days','number')}<div class="impact-note">The comparison below is a <b>fixed design example</b>; sliders stage settings and do not calculate a new engine result.</div></div></div><div class="footer-action"><span>Versions and inputs remain attached to both runs.</span>${link('See the town','simulation')}</div>`;}
function experimentResults(){return `${heading('The same town. A different outcome.','Compare matched sample runs before changing the operating model.',link('Edit experiment','config'),'EXPERIMENT 007 / RESULTS')}<div class="studio-ribbon">${icon('flask')}<span>Baseline <b>35% coverage</b></span><span>Treatment <b>80% coverage</b></span><span><b>Illustrative example</b> · Fixed sample values</span></div><div class="grid2"><div class="card"><div class="metric-compare header"><span>Metric</span><span>A · Baseline</span><span>B · Treatment</span><span>Change</span></div>${[['Days to release','4.2','1.8','−57%'],['Human reviews','240','84','−65%'],['Processing cost','$8,880','$4,440','−50%'],['Carrying cost','$1,925','$825','−57%']].map(([l,a,b,d])=>`<div class="metric-compare"><span>${l}</span><span class="big muted">${a}</span><span class="big">${b}</span><span class="delta">${d}</span></div>`).join('')}<p class="small" style="margin-top:20px">Days per case · Costs in CAD for the sample period · Not a financial forecast.</p></div><div class="card"><div class="label">What explains the change</div><h2 style="margin:14px 0">Fewer cases wait for a person.</h2><p class="small">Higher rule coverage reduces analyst review volume. The remaining cases still enter the same queues, with the same billing controls.</p><div class="section-rule"></div><div class="details-list"><span>VEE precision</span><strong>96%</strong><span>VEE recall</span><strong>93%</strong><span>Read population</span><strong>1,440</strong></div><div style="margin-top:22px">${link('Inspect a sample case','billing',true)}</div></div></div><div class="card" style="margin-top:22px"><div class="card-header"><h2>Open backlog across the period</h2><div class="legend"><span><i class="grey"></i>A · Baseline</span><span><i></i>B · Treatment</span></div></div>${chart()}</div>`;}
function focusMap(){return `<section class="focus-map" aria-label="Interactive utility town"><div class="map-slot"></div><div class="focus-map-tools" aria-label="Map controls">${[['electric','Electricity','ϟ'],['water','Water','W'],['gas','Gas','G']].map(([v,l,s])=>`<button data-action="layer" data-layer="${v}" class="${(state.layer||'electric')===v?'on':''}" aria-label="${l} network" title="${l} network" aria-pressed="${(state.layer||'electric')===v}">${s}</button>`).join('')}<span></span><button data-action="fit" aria-label="Fit town" title="Fit town">${icon('town')}</button></div><a class="focus-attribution" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a></section>`;}

function focusSettings(){return `<div class="focus-document focus-settings">${configForm()}<div class="footer-action"><span id="draft-note">${state.dirty?'Draft changes':'Settings saved'} · Revision ${state.revision}</span>${btn('Save settings & open map','save',true)}</div></div>`;}
function focusResults(){return `<div class="focus-document"><div class="focus-result-tools"><div class="legend"><span><i class="grey"></i>Baseline · 35% coverage</span><span><i></i>Treatment · 80% coverage</span></div>${btn(`${icon('download')} Export`,'export')}</div><div class="card"><div class="metric-compare header"><span>Metric</span><span>Baseline</span><span>Treatment</span><span>Change</span></div>${[['Days to release','4.2','1.8','−57%'],['Human reviews','240','84','−65%'],['Processing cost','$8,880','$4,440','−50%'],['Carrying cost','$1,925','$825','−57%']].map(([l,a,b,d])=>`<div class="metric-compare"><span>${l}</span><span class="big muted">${a}</span><span class="big">${b}</span><span class="delta">${d}</span></div>`).join('')}</div><div class="card"><div class="card-header"><h3>Open exception backlog</h3><span class="small">Illustrative sample · CAD</span></div>${chart()}</div></div>`;}
function experiment(){const screen=state.page==='simulation'?focusMap():state.page==='sap'?sapWorkspace():focusSettings();return `<div class="shell experiment focus-shell"><header class="top focus-header simple-header">${brand('Utility Studio')}<nav class="studio-tabs" aria-label="Workspace">${[['simulation','Map'],['sap','Workspace']].map(([p,l])=>`<a href="${p==='sap'?state.lastSapRoute:route(p)}" class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''}>${l}</a>`).join('')}</nav><a class="focus-settings-link ${state.page==='config'?'active':''}" href="${route('config')}" title="Configuration" aria-label="Configuration" ${state.page==='config'?'aria-current="page"':''}>${icon('cog')}</a></header><main class="focus-main focus-${state.page}">${screen}</main></div>`;}

function spatialPanel(){if(state.page==='config')return `<div class="label">Run configuration</div><h2>Keep the town.<br>Change the process.</h2><p class="small">Settings stay next to the town they affect.</p>${slider('coverage','RPA coverage',0,100,'%','Share of exception types auto-resolved.')}${field('queue','Analyst queue wait · days')}${field('carry','Carrying cost · CAD / day')}<div class="impact-note">Applies to the next run.<br><b>Town geometry stays fixed.</b></div>${btn('Save & preview run','save',true)}`;if(state.page==='billing')return `<div class="row between"><span class="label">Worklists</span><span class="pill warn">48 open</span></div><h2>Cases in this town</h2><p class="small">Select a sample case to inspect its read and billing context.</p>${cases.slice(0,4).map((c,i)=>`<button class="queue-mini" data-case="${i}"><div class="row between"><b>${c.type}</b><span class="pill warn">${money(c.impact)}</span></div><p>${c.address} · ${c.age} days old</p><p>${c.next}</p></button>`).join('')}${link('SAP-style billing view','sap',true)}`;if(state.page==='results')return `<div class="label">Run results</div><h2>Town to outcome.</h2><p class="small">October cycle · illustrative sample</p><div class="summary-stat">96.7% <span class="small">first pass</span></div><div class="section-rule"></div><div class="details-list"><span>Reads collected</span><strong>1,440</strong><span>Released to billing</span><strong>1,392</strong><span>Average days to release</span><strong>1.8</strong><span>Human reviews</span><strong>84</strong></div><div class="section-rule"></div><h3>Cost of processing</h3>${costs()}${btn('Export sample summary','export')}`;return `<div class="row between"><span class="label">Run SIM-042</span><span class="pill good">Sample complete</span></div><h2>October read cycle</h2><p class="small">Follow a read from this town into VEE and the billing back office.</p><div class="section-rule"></div>${events()}<div class="card"><div class="label">Next action</div><h3 style="margin-top:10px">48 exceptions need review</h3><p class="small" style="margin-top:7px">High-impact cases first.</p>${link('Open worklists','billing',true)}</div>`;}
function spatial(){return `<div class="shell spatial">${contextTop()}${state.page==='sap'?`<main class="page">${sapPage()}</main>`:`<div class="spatial-layout"><nav class="spatial-rail">${stages.map(([p,l,i])=>`<a href="${route(p)}" class="${state.page===p?'active':''}">${icon(i)}<span>${p==='billing'?'Worklists':l}</span></a>`).join('')}<a href="${route('sap')}">${icon('file')}<span>Back office</span></a></nav><div class="spatial-stage">${map('')}<div class="journey-dock"><div class="row between"><h3>October meter-to-cash run</h3><span class="small">SIM-${state.run.toString().padStart(3,'0')}</span></div>${flow()}</div></div><aside class="spatial-panel">${spatialPanel()}</aside></div>`}</div>`;}
function content(){return state.page==='config'?configPage():state.page==='simulation'?simulationPage():state.page==='billing'?billingPage():state.page==='sap'?sapPage():resultsPage();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function openDialog(title,html){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${html}`;$('#dialog').showModal();}
function about(){openDialog('Four ways to connect Utility Sim',`<div class="dialog-copy">${Object.entries(concepts).map(([id,c],i)=>`<div class="concept-option"><strong>${i+1}. ${c.label}</strong>${c.best}</div>`).join('')}<p style="margin-top:20px">Grounded in the current Utility Sim town viewer and the active engine branch’s VEE worklists, configuration, actions and cost catalogue. The SAP-style screens reuse the field names, record structure, tab order and visual conventions from your M2C Transaction Lab.</p><p><b>This is a design prototype.</b> The 3D renderer and town snapshot are existing project assets. Run counts, case details, results and billing records are illustrative; there is no live engine or SAP connection. Billing documents, print documents and back-office navigation demonstrate the proposed connection.</p><p>You can change draft settings, navigate all four workflows, filter cases, inspect a case and move into its billing back office. Changes stay in this browser session.</p></div>`);}
function openCase(index){if(reviewMeterRead(index))return;state.selected=index;const c=cases[index];openDialog(`${c.type} · ${c.id}`,`<div class="row between"><p class="small">${c.address} · ${c.utility} · Sample case</p><span class="pill warn">${c.queue}</span></div><div class="details-list"><span>Contract account</span><strong>${c.account}</strong><span>Bill impact</span><strong>${money(c.impact)}</strong><span>Age</span><strong>${c.age} business days</strong><span>VEE diagnosis</span><strong>${c.code}</strong><span>Confidence</span><strong>${c.confidence===null?'No read':c.confidence+'%'}</strong></div><div class="section-rule"></div><h3>Why it is held</h3><div class="case-tests"><div class="case-test"><span>Temporal validity</span><b class="test-pass">Pass</b></div><div class="case-test"><span>Consistency checks</span><b class="${c.confidence===null?'test-fail':'test-pass'}">${c.confidence===null?'Read unavailable':'Pass'}</b></div><div class="case-test"><span>Process corroboration</span><b class="test-fail">${c.type}</b></div></div><h3>Activity sequence</h3><div class="case-trace"><p>Read evaluated / missing read detected<small>01 Oct 2026 · 01:04</small></p><p>Exception queued for ${c.queue.toLowerCase()}<small>Bill remains held · ${money(c.impact)} sample impact</small></p><p>${state.resolved.has(c.id)?'Released in preview':'Awaiting '+c.next.toLowerCase()}<small>Changes in this prototype do not reach SAP or the engine.</small></p></div><div class="row wrap" style="margin-top:22px">${btn('Open billing back office','case-sap',true)}${btn(state.resolved.has(c.id)?'Released in preview':'Preview release','release',false,state.resolved.has(c.id)?'disabled':'')}</div>`);}
let mapNode=null,townScene=null,mapTask=null;
async function mountMap(){const slot=$('.map-slot');if(!slot){if(townScene)townScene.suspended=true;return;}if(!mapNode){mapNode=document.createElement('div');mapNode.style.cssText='position:absolute;inset:0';mapNode.innerHTML='<div class="map-message"><b>Loading the existing town…</b><span>Whitby / 480 homes</span></div>';}slot.append(mapNode);if(townScene){townScene.suspended=false;townScene.resize();return;}if(mapTask)return;mapTask=(async()=>{try{const [{TownScene},r]=await Promise.all([import('./viewer/scene.js'),fetch('./viewer/town.json.gz')]);if(!r.ok)throw new Error('Town fixture unavailable');const stream=r.body.pipeThrough(new DecompressionStream('gzip')),town=await new Response(stream).json();mapNode.replaceChildren();townScene=new TownScene(mapNode,({home})=>{if(home)openDialog('Town property',`<p class="dialog-copy">${esc(home.address||home.id)} · Existing engine snapshot</p><div class="details-list"><span>Premise</span><strong>${esc(home.id)}</strong><span>Account</span><strong>${esc(home.accountId||'Not supplied')}</strong><span>Service connections</span><strong>${esc((Array.isArray(home.services)?home.services:Object.keys(home.services||{})).join(', '))}</strong></div><p class="small" style="margin-top:22px">The design worklist uses separate illustrative cases. Full case-to-map identity matching belongs to the engine integration.</p><div style="margin-top:20px">${btn('Open sample worklists','map-cases',true)}</div>`);});townScene.play=false;townScene.load(town,{demo:false});townScene.setClock({hour:12,sunElevationDeg:50,sunAzimuthDeg:135});townScene.setLayers({electric:!state.layer||state.layer==='electric',water:state.layer==='water',gas:state.layer==='gas'});townScene.setXray(false);townScene.suspended=!$('.map-slot');}catch(err){mapNode.innerHTML='<div class="map-message"><b>3D preview unavailable on this device</b><span>You can still explore configuration and the workspace.</span></div>';console.warn('Town preview:',err.message);}})();}
function parseRoute(){
 const [,p,t,id]=location.hash.slice(1).split('/');
 state.concept='experiment';
 state.page=p==='config'?'config':['billing','sap','workspace','vee','exceptions'].includes(p)?'sap':'simulation';
 if(state.page==='sap'){
  let transaction=p==='billing'?'exceptions':p==='vee'||p==='exceptions'?p:[...sapTransactions.map(entry=>entry[1]),...Object.keys(sapScreenNames)].includes(t)?t:'exceptions';
  if(transaction==='field-order'&&!hasFieldOrderDraft())transaction='exceptions';
  if(billingScreens.includes(transaction)&&state.billingIndex!==state.selected)transaction='billing-query';
  if(readingScreens.includes(transaction)&&state.readIndex!==state.selected)transaction='read-query';
  if(transaction.endsWith('-query')&&state.queryKind!==transaction){state.queryKind=transaction;state.queryValue='';state.queryError='';}
  state.sapTransaction=transaction;state.sapRecord=transaction==='exceptions'?(p==='exceptions'?t:id)||'':'';
  if(Object.hasOwn(sapScreenNames,transaction))state.sapTab=transaction;
  state.lastSapRoute=route('sap/'+transaction+(state.sapRecord?'/'+state.sapRecord:''),'experiment');
 }
 const canonical=state.page==='sap'?state.lastSapRoute:route(state.page);
 if(location.hash!==canonical)window.history.replaceState(null,'',canonical);
}
function render(){if(mapNode?.parentElement)mapNode.remove();parseRoute();document.body.classList.toggle('studio-focus',state.concept==='experiment');document.body.classList.toggle('sap-workspace',state.concept==='experiment'&&['billing','vee','exceptions','sap'].includes(state.page));$('#concepts').innerHTML=Object.entries(concepts).map(([c,v],i)=>`<a href="#${c}/${c==='control'?'overview':['spatial','experiment'].includes(c)?'simulation':'config'}" class="${c===state.concept?'current':''}" ${c===state.concept?'aria-current="page"':''}><span>0${i+1}</span>${v.label}</a>`).join('');$('#concept-note').innerHTML=`<div class="concept-note"><span><b>${concepts[state.concept].label}.</b> ${concepts[state.concept].note}</span><span class="fixture">Interactive mockup · Sample data</span></div>`;$('#app').innerHTML=({guided,control,experiment,spatial}[state.concept])();mountMap();document.title=`${state.page==='sap'?'Workspace':state.page==='config'?'Configuration':'Map'} · Utility Studio`;}
function markDraft(){state.dirty=true;const el=$('#config-status');if(el){el.className='pill warn';el.textContent='Draft changes';}const d=$('#draft-note');if(d)d.textContent='Changes apply to the next preview.';}
function save(){state.revision++;state.savedRevision=state.revision;state.dirty=false;state.run++;toast('Draft configuration saved for this concept preview.');location.hash=route('simulation');}
function exportSummary(){const body={type:'utility-sim-design-sample',notEngineOutput:true,concept:state.concept,town:'Whitby',sampleRun:state.run,configuration:{...state.config},configurationRevision:state.savedRevision,illustrativeResults:{reads:1440,accepted:1392,openCases:48,processingCostCAD:4440,carryingCostCAD:825,averageDaysToRelease:1.8},previewReleasedCases:[...state.resolved]};const u=URL.createObjectURL(new Blob([JSON.stringify(body,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='utility-sim-sample-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Illustrative sample summary exported.');}
function clock(){const v=$('#clock-value');if(v)v.textContent=String(state.hour).padStart(2,'0')+':00';const sl=$('#clock-slider');if(sl)sl.value=state.hour;townScene?.setClock({hour:state.hour,sunElevationDeg:55*Math.sin((state.hour-6)/12*Math.PI),sunAzimuthDeg:90+(state.hour-6)*15});}
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.config){const key=el.dataset.config;let v=el.type==='number'||el.type==='range'?Number(el.value):el.value;if(el.type==='number'&&(!el.validity.valid||!Number.isFinite(v)))return;state.config[key]=v;const val=$(`[data-value="${key}"]`);if(val)val.textContent=v+(el.dataset.suffix||'');markDraft();}if(el.id==='sap-query-id'){state.queryValue=el.value;state.queryError='';const message=$('#sap-query-error');if(message)message.textContent='';}if(el.id==='case-search'){state.search=el.value;$('#case-table').innerHTML=queueTable();}if(el.id==='clock-slider'){state.hour=Number(el.value);clock();}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='sap-transaction'){openSapTransaction(el.value);return;}if(el.tagName==='SELECT'&&el.dataset.config){state.config[el.dataset.config]=el.value;markDraft();}});
document.addEventListener('keydown',ev=>{const t=ev.target.closest('[data-case]');if(t&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();openCase(Number(t.dataset.case));}});
document.addEventListener('click',ev=>{const tab=ev.target.closest('[data-tab]');if(tab){state.configTab=tab.dataset.tab;render();return;}const q=ev.target.closest('[data-queue]');if(q){state.queue=q.dataset.queue;render();return;}const c=ev.target.closest('[data-case]');if(c){openCase(Number(c.dataset.case));return;}const pick=ev.target.closest('[data-query-pick]');if(pick){state.queryValue=pick.dataset.queryPick;state.queryError='';$('#dialog').close();render();$('#sap-query-id')?.focus();return;}const st=ev.target.closest('[data-sap]');if(st){if(state.concept==='experiment')openSapRelated(st.dataset.sap);else{state.sapTab=st.dataset.sap;render();}return;}const t=ev.target.closest('[data-action]');if(!t)return;const action=t.dataset.action;if(action==='query-help')queryHelp();if(action==='query-clear'){state.queryValue='';state.queryError='';render();$('#sap-query-id')?.focus();}if(action==='query-new')openSapTransaction(t.dataset.queryKind);if(action==='read-back'){const target=state.readOrigin;if(target)location.hash=target;else openSapTransaction('read-query');}if(action==='about')about();if(action==='designs')openDialog('Portal concepts',`<nav class="concept-picker">${Object.entries(concepts).map(([id,c],i)=>`<a href="#${id}/${id==='control'?'overview':['spatial','experiment'].includes(id)?'simulation':'config'}" data-action="close"><span>0${i+1}</span><strong>${c.label}</strong>${id==='experiment'?'<small>Focus mode</small>':''}</a>`).join('')}</nav>`);if(action==='close')$('#dialog').close();if(action==='save'){if(!$$('input').every(i=>i.checkValidity())){$$('input').find(i=>!i.checkValidity())?.reportValidity();return;}save();}if(action==='compare'){state.savedRevision=++state.revision;state.dirty=false;location.hash=route('results');toast('Showing the fixed 35% vs 80% sample comparison.');}if(action==='export')exportSummary();if(action==='case-sap'){$('#dialog').close();if(state.concept==='experiment')openSapTransaction('orders');else{state.sapTab='orders';location.hash=route('sap');}}if(action==='release'){const selected=cases[state.selected];state.resolved.add(selected.id);$('#dialog').close();render();toast('Read released in the preview only.');}if(action==='map-cases'){$('#dialog').close();location.hash=route('billing');}if(action==='fit')townScene?.home();if(action==='layer'){const layer=t.dataset.layer;state.layer=layer;townScene?.setLayers({electric:layer==='electric',water:layer==='water',gas:layer==='gas'});$$('[data-action=layer]').forEach(b=>{b.classList.toggle('on',b===t);b.setAttribute('aria-pressed',String(b===t));});}if(action==='play'){state.playing=!state.playing;t.innerHTML=state.playing?'Ⅱ':icon('play');t.setAttribute('aria-label',state.playing?'Pause lighting preview':'Play lighting preview');clearInterval(state.timer);if(state.playing)state.timer=setInterval(()=>{state.hour=(state.hour+1)%24;clock();},1500);}if(action==='sap-case')openCase(state.selected);if(action==='sap-worklist')location.hash=state.worklistReturn||route(cases[state.selected].readDetails?'vee':'exceptions','experiment');if(action==='sap-release'){if(reviewMeterRead(state.selected))return;state.resolved.add(cases[state.selected].id);render();toast('Sample billing block cleared in preview only.');}if(action==='sap-refresh')toast('The illustrative billing record is up to date.');});
document.addEventListener('submit',ev=>{if(ev.target.id==='sap-query-form'){ev.preventDefault();submitSapQuery(ev.target.dataset.queryKind,ev.target.elements.identifier.value);}});
document.addEventListener('keydown',ev=>{if(ev.key==='F4'&&ev.target.id==='sap-query-id'){ev.preventDefault();queryHelp();}});
window.addEventListener('hashchange',()=>{clearInterval(state.timer);state.playing=false;render();window.scrollTo(0,0);});
function sapTable(headers,rows){return `<div class="sap-table"><table><thead><tr><th style="width:23px"></th>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="sap-row-no">${i+1}</td>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function sapLink(text,to){return `<button class="sap-link" data-sap="${to}">${text}</button>`;}
function sapField(label,value,linkTo=''){return `<div class="sap-field"><label>${label}</label>${linkTo?sapLink(value,linkTo):`<span class="sap-input">${value}</span>`}</div>`;}
function sapPage(focus=false){const c=cases[state.selected],tab=state.sapTab,clear=state.resolved.has(c.id),n=c.id.slice(2),unit=c.utility==='Gas'?'CCF':c.utility==='Water'?'m³':'kWh',rate=c.utility==='Gas'?'GAS_RES':c.utility==='Water'?'WATER_RES':'ELEC_RES',ids={installation:'710000'+n,contract:state.selected===0?'4100000101':'410000'+n,account:c.account,device:'DM26'+c.utility[0]+'0'+n,partner:state.selected===0?'1100000101':'110000'+n,doc:state.selected===0?'5100000880':'510000'+n,print:state.selected===0?'8100000880':'810000'+n},title={orders:'Billing view of installation',reads:'Display Meter Reading Results',contract:'Display Contract',document:'Display Billing Document',invoice:'Display Print Document',installation:'Display Installation',device:'Display Device and Register',rates:'Display Rate Data',periods:'Billing view of installation',documents:'Billing view of installation'}[tab]||'Billing view of installation';
const rd=c.readDetails||{register:1240,previous:1240,expected:1268,upper:1640,releasedRegister:1268},fmt=v=>Number(v).toLocaleString('en-CA'),readValue=fmt(clear?rd.releasedRegister:rd.register),readDate=rd.scheduled||'10/01/2026';
let body='';
if(tab==='orders')body=`<h3 class="sap-section-title">Billing Orders</h3>${sapTable(['Installation','Schd MRD','Status','Contract','Short Descript.'],[[sapLink(ids.installation,'installation'),sapLink(readDate,'reads'),`<span class="sap-square ${clear?'green':''}"></span>${clear?'Ready':'Blocked'}`,sapLink(ids.contract,'contract'),'Periodic billing (01)']])}<div class="sap-explain">${clear?'Preview: reading review block cleared.':'Billing block 01 · Reading review. Inspect the meter reading and contract before release.'} No billing or invoicing run is executed by this prototype.</div>`;
if(tab==='periods')body=`<h3 class="sap-section-title">Current Billing Periods</h3>${sapTable(['Installation','Contract','Status','Move-in date','Move-out date','Contract account'],[[sapLink(ids.installation,'installation'),sapLink(ids.contract,'contract'),'Active','07/01/2026','12/31/9999',ids.account],[ids.installation,'4100000098','Ended','01/01/2025','06/30/2026','2100000098']])}`;
if(tab==='documents')body=`<h3 class="sap-section-title">Billing Documents</h3>${sapTable(['Billing document','Start billing period','End billing period','Contract','Print document','Description'],[[sapLink(ids.doc,'document'),'09/01/2026','09/30/2026',sapLink(ids.contract,'contract'),sapLink(ids.print,'invoice'),'Periodic billing (01)']])}`;
if(tab==='reads')body=`<div class="sap-object"><div>${sapField('Device',ids.device,'device')}${sapField('Installation',ids.installation,'installation')}${sapField('Register','1')}</div><div>${sapField('Scheduled MR date',readDate)}${sapField('MR doc.','MR-2026-'+n)}${sapField('Unit of meas.',unit)}</div></div><div class="sap-minitabs"><span class="selected">Page 1</span><span>Values / dates / control</span></div><div class="sap-form"><h3>Meter Reading Result</h3>${sapField('Meter reading',readValue)}${sapField('Meter reading for billing',readValue)}${sapField('Expected MR',fmt(rd.expected))}${sapField('Upper limit of MR',fmt(rd.upper))}${sapField('Lower limit of MR',fmt(rd.previous))}${sapField('Unit of meas. for MR',unit)}${sapField('MR status',clear?(rd.status||'Released · preview'):'Implausible / review')}${sapField('Validation class',rate)}</div><h3 class="sap-section-title">Billing-Relevant Meter-Reading Results</h3>${sapTable(['Schd MR date','MR result','MR for billing','MR type','Status','Reason'],[[readDate,readValue,readValue,'04',clear?'Released':'Review','01'],['09/01/2026',fmt(rd.previous),fmt(rd.previous),'04','Released','01']])}`;
if(tab==='contract')body=`<div class="sap-object">${sapField('Contract',ids.contract)}${sapField('Installation',ids.installation,'installation')}${sapField('Contract Acct',ids.account)}</div><div class="sap-minitabs"><span>Page 1</span><span class="selected">Page 2 · Billing</span><span>Page 3</span></div><div class="sap-form"><h3>Billing-relevant data</h3>${sapField('Joint Invoicing','1 · Separate')}${sapField('Tax Jur.','ON00000000')}${sapField('Bill.blck.reas.',clear?'No block':'01 · Reading review')}${sapField('Outsort.chk grp',rate)}${sapField('Man. OS billing','')}${sapField('No. outsortings','1')}${sapField('Dunning Proc.','0001')}${sapField('Invoicing Lock',hasInvoiceHold(state.selected)?'Clarification hold':'No lock')}${sapField('OSB Group','Not active')}</div><div class="sap-explain">${clear?'The sample block is cleared.':'A reading-review block is holding the billing order.'} ${sapLink('Inspect meter reading results','reads')}</div>`;
if(tab==='installation')body=`<div class="sap-object">${sapField('Installation',ids.installation)}${sapField('Premise','610000'+n)}${sapField('Address',esc(c.address))}${sapField('Business partner',ids.partner)}</div><div class="sap-form"><h3>General Data</h3>${sapField('Division',c.utility==='Gas'?'02 · Gas':c.utility==='Water'?'03 · Water':'01 · Electricity')}${sapField('Rate Category',rate)}${sapField('MR control','01')}${sapField('Time Zone','America/Toronto')}${sapField('Meter reading unit','G-021')}${sapField('Portion','P-021')}</div><h3 class="sap-section-title">Device Data</h3>${sapTable(['Device','Register','Valid from','Valid to','Rate type'],[[sapLink(ids.device,'device'),'1','01/01/2024','12/31/9999',sapLink(rate,'rates')]])}`;
if(tab==='device')body=`<div class="sap-object">${sapField('Device',ids.device)}${sapField('Installation',ids.installation,'installation')}</div><div class="sap-form"><h3>IS Data</h3>${sapField('Device category',c.utility+' meter · AMR')}${sapField('Device info','Synthetic demo device')}${sapField('Register Group','001')}${sapField('Disconn. Status','Connected')}</div><h3 class="sap-section-title">Register Data</h3>${sapTable(['Register','Register category','MR unit','Billing unit','Predecimal','Decimal'],[['1','Consumption',unit,unit,'4','0']])}`;
if(tab==='rates')body=`<div class="sap-object">${sapField('Installation',ids.installation,'installation')}${sapField('Rate Category',rate)}</div><h3 class="sap-section-title">Device & Register Rates</h3>${sapTable(['Device','Register','Rate type','Valid from','Valid to','Rate fact'],[[sapLink(ids.device,'device'),'1',rate,'01/01/2026','12/31/9999','1.000']])}<div class="sap-explain">Synthetic rate records for navigation only. The portal does not calculate a tariff or execute billing.</div>`;
if(tab==='document'||tab==='invoice')body=`<div class="sap-document-layout"><aside><h3>Document selection</h3>${sapField('Installation',ids.installation)}<div class="sap-tree"><div>▾ ${tab==='invoice'?'Print':'Billing'} document</div><div> &nbsp; ▾ ${tab==='invoice'?ids.print:ids.doc}</div><div>&nbsp; &nbsp; Header data</div><div>&nbsp; &nbsp; Scheduled data</div><div>&nbsp; &nbsp; Line items</div></div></aside><section><div class="sap-object">${sapField(tab==='invoice'?'Print document':'Billing document',tab==='invoice'?ids.print:ids.doc)}${sapField('Contract',ids.contract,'contract')}${sapField('Contract Acct',ids.account)}</div><div class="sap-minitabs"><span class="selected">MasterData</span><span>Sched. Data</span></div><div class="sap-form"><h3>Header Data</h3>${sapField('Start billing period','09/01/2026')}${sapField('End billing period','09/30/2026')}${sapField('Billing transaction','01 · Periodic')}${sapField('Currency','CAD')}${sapField('Document status','Sample historical document')}${tab==='document'?sapField('Print document',ids.print,'invoice'):sapField('Billing document',ids.doc,'document')}</div>${sapTable(['Line','Description','Quantity','Unit','Amount'],[['001','Customer charge','1','MO','26.50'],['002',c.utility+' consumption','28',unit,'28.54'],['003','Tax · sample','','','7.16'],['','Total · sample','','CAD','62.20']])}</section></div>`;
const decorated=`${heading('Billing back office','SAP-style transaction screens, connected to the selected case.',link('Back to worklists','billing'))}<div class="sap-context"><div><span>SELECTED CASE</span><b>${c.id} · ${c.type}</b></div><div><span>CONTRACT ACCOUNT</span><b>${c.account}</b></div><div><span>RUN</span><b>SIM-${state.run.toString().padStart(3,'0')}</b></div>${btn('Inspect VEE decision','sap-case')}</div><div class="sap-app"><header class="sap-top"><span class="sap-emblem">SAP</span><span>${title}</span><small>100 ▾</small></header><div class="sap-toolbar"><button data-sap="installation">${icon('town')} Installation</button><button data-sap="contract">${icon('file')} Contract</button><button data-sap="reads">${icon('grid')} MR results</button><span class="sap-toolbar-rule"></span><button data-action="sap-worklist">Back to case / list</button><button data-action="sap-refresh">Refresh</button><button data-action="sap-release" ${clear?'disabled':''}>${icon('check')} Preview release</button></div><nav class="sap-tabs" aria-label="SAP-style transaction tabs">${[['periods','Bil.Time'],['documents','Document'],['orders','Bil. Order'],['rates','Rate Types'],['device','Register'],['reads','MR result'],['contract','Block'],['invoice','Print doc.']].map(([v,l])=>`<button data-sap="${v}" class="${tab===v?'active':''}">${icon('grid')}${l}</button>`).join('')}</nav><div class="sap-body">${body}</div><div class="sap-status"><span class="sap-square green"></span> Synthetic transaction preview · No connection to SAP <span class="spacer"></span><span>IS-U / ${ids.installation}</span></div></div><div class="footer-action"><span>Screen conventions from your M2C Transaction Lab · Financial and case data are illustrative.</span>${link('View run results','results')}</div>`;
return focus?`<div class="sap-app">${sapTransactionHeader(tab)}${sapRecordToolbar(tab)}${sapRecordTabs(tab)}<div class="sap-body">${body}</div><div class="sap-status"><span class="sap-square green"></span> Synthetic transaction preview · No connection to SAP <span class="spacer"></span><span>IS-U / ${ids.installation}</span></div></div>`:decorated;
}
installExceptionWorkspaces({state,cases,icon,esc,route,btn,money,openDialog,toast,render,sapTransactionHeader,openSapTransaction,openSapRelated,canReviewMeterRead});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'get_portal_preview',description:'Read the selected Utility Sim concept and draft settings. All outputs are design sample data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({concept:state.concept,page:state.page,transaction:state.page==='sap'?state.sapTransaction:null,config:{...state.config},sampleData:true})},{name:'navigate_portal_preview',description:'Open the Utility Studio map, configuration or workspace. Record entry still requires the SAP query flow. Does not run the engine or SAP.',inputSchema:{type:'object',properties:{concept:{type:'string',enum:['experiment']},page:{type:'string',enum:['config','simulation','billing','sap','vee','exceptions']}},required:['concept','page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||input.concept!=='experiment'||!['config','simulation','billing','sap','vee','exceptions'].includes(input.page))throw Error('Choose a valid concept and workflow page.');location.hash=`#${input.concept}/${input.page}`;render();return{concept:state.concept,page:state.page,sampleData:true};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
